query GetAgentRunResumeConfig($runId: String!) {
  getAgentRunResumeConfig(runId: $runId) {
    runId
    isActive
    metadataConfig {
      agentDefinitionId
      workspaceRootPath
      llmModelIdentifier
      llmConfig
      autoExecuteTools
      runtimeKind
      runtimeReference {
        runtimeKind
        sessionId
        threadId
        metadata
        __typename
      }
      __typename
    }
    modelConfigEditability {
      editable
      reason
      __typename
    }
    __typename
  }
}

